import { DashboardShell } from "@/components/DashboardShell";
import { getDashboardSnapshot } from "@/lib/queries";

export const dynamic = "force-dynamic";

export default async function Home() {
  const initialSnapshot = await getDashboardSnapshot();

  return <DashboardShell initialSnapshot={initialSnapshot} />;
}

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Command Center",
  description: "Live ride-hailing operations dashboard",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full bg-midnight text-white">{children}</body>
    </html>
  );
}

export type ProfileRole = "passenger" | "driver" | "admin";

export type RideStatus =
  | "requested"
  | "accepted"
  | "en_route"
  | "arrived"
  | "in_progress"
  | "completed"
  | "cancelled";

export type PaymentMethod = "cash" | "mmg" | string;
export type PaymentStatus = "pending" | "completed" | "failed" | "refunded" | string;

export type Profile = {
  id: string;
  full_name: string | null;
  phone: string | null;
  role: ProfileRole;
  created_at: string;
};

export type Driver = {
  id: string;
  is_online: boolean;
  current_lat: number | null;
  current_lng: number | null;
  current_location_updated_at: string | null;
  rating_avg: number | null;
  total_rides: number | null;
  license_plate: string | null;
  vehicle_info: Record<string, unknown> | null;
};

export type Ride = {
  id: string;
  passenger_id: string;
  driver_id: string | null;
  status: RideStatus;
  pickup_lat: number;
  pickup_lng: number;
  dropoff_lat: number;
  dropoff_lng: number;
  pickup_address: string | null;
  dropoff_address: string | null;
  fare_estimate: number | null;
  fare_final: number | null;
  payment_method: PaymentMethod | null;
  payment_status: PaymentStatus | null;
  created_at: string;
  accepted_at: string | null;
  arrived_at: string | null;
  started_at: string | null;
  completed_at: string | null;
};

export type Payment = {
  ride_id: string;
  method: PaymentMethod;
  amount: number;
  status: PaymentStatus;
  reference: string | null;
};

export type OnlineDriver = Driver & {
  profiles: Pick<Profile, "full_name"> | null;
};

export type RequestedRide = Ride & {
  profiles: Pick<Profile, "full_name"> | null;
};

export type ActiveTrip = Ride & {
  passenger: Pick<Profile, "full_name"> | null;
  driver_profile: Pick<Profile, "full_name"> | null;
};

export type DashboardStats = {
  onlineDrivers: number;
  requestedRides: number;
  activeTrips: number;
  completedToday: number;
  revenueToday: number;
};

export type DashboardSnapshot = {
  onlineDrivers: OnlineDriver[];
  requestedRides: RequestedRide[];
  activeTrips: ActiveTrip[];
  stats: DashboardStats;
};

"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { HeaderStats } from "./HeaderStats";
import { PendingRequestsPanel } from "./PendingRequestsPanel";
import { ActiveTripsPanel } from "./ActiveTripsPanel";
import { ActivityFeedPanel } from "./ActivityFeedPanel";
import { DesktopGate } from "./DesktopGate";
import type { DashboardSnapshot } from "@/types/database";
import type { ActivityEvent } from "@/types/activity";

const OperationsMap = dynamic(() => import("./OperationsMap"), {
  ssr: false,
  loading: () => <div className="h-full min-h-[560px] rounded-xl bg-[#111] animate-pulse" />,
});

type ConnectionStatus = "connecting" | "connected" | "reconnecting";

export function DashboardShell({ initialSnapshot }: { initialSnapshot: DashboardSnapshot }) {
  const [snapshot, setSnapshot] = useState(initialSnapshot);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [activityEvents, setActivityEvents] = useState<ActivityEvent[]>([]);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>("connecting");
  const [clock, setClock] = useState<Date | null>(null);

  useEffect(() => {
    setLastUpdated(new Date());
    setClock(new Date());
    const interval = setInterval(() => setClock(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let es: EventSource | null = null;
    let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    let intentionalClose = false;

    function connect() {
      if (intentionalClose) return;
      setConnectionStatus((prev) => (prev === "connected" ? "reconnecting" : "connecting"));

      es = new EventSource("/api/events");

      es.addEventListener("snapshot", (e) => {
        try {
          const data = JSON.parse(e.data) as DashboardSnapshot;
          setSnapshot(data);
          setLastUpdated(new Date());
          setConnectionStatus("connected");
        } catch (err) {
          console.error("Failed to parse snapshot event", err);
        }
      });

      es.addEventListener("activity", (e) => {
        try {
          const data = JSON.parse(e.data) as ActivityEvent;
          setActivityEvents((prev) => [data, ...prev].slice(0, 200));
        } catch (err) {
          console.error("Failed to parse activity event", err);
        }
      });

      es.onopen = () => {
        setConnectionStatus("connected");
      };

      es.onerror = () => {
        setConnectionStatus("reconnecting");
        if (es) {
          es.close();
          es = null;
        }
        if (!intentionalClose) {
          if (reconnectTimer) clearTimeout(reconnectTimer);
          reconnectTimer = setTimeout(() => {
            reconnectTimer = null;
            connect();
          }, 3000);
        }
      };
    }

    connect();

    return () => {
      intentionalClose = true;
      if (reconnectTimer) clearTimeout(reconnectTimer);
      if (es) {
        es.close();
        es = null;
      }
    };
  }, []);

  const statusLabel =
    connectionStatus === "connected"
      ? { text: "LIVE", color: "#22c55e" }
      : { text: "RECONNECTING", color: "#f59e0b" };

  return (
    <DesktopGate>
      <main className="min-h-screen bg-midnight p-4 text-white lg:p-6">
        <div className="mx-auto flex max-w-[1800px] flex-col gap-4">
          <header className="flex items-center justify-between rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] px-4 py-3 backdrop-blur-md">
            <div className="flex items-center gap-4">
              <div className="mb-0.5 flex items-center gap-3 text-xs font-semibold uppercase tracking-[0.28em] text-accent">
                <span
                  className="h-2.5 w-2.5 animate-pulse rounded-full"
                  style={{
                    backgroundColor: statusLabel.color,
                    boxShadow: `0 0 16px ${statusLabel.color}`,
                  }}
                />
                {statusLabel.text}
              </div>
              <div className="h-5 w-px bg-[rgba(255,255,255,0.1)]" />
              <h1 className="text-xl font-semibold tracking-tight">Command Center</h1>
            </div>

            <div className="flex items-center gap-4">
              <div className="text-right">
                <div className="text-[11px] uppercase tracking-[0.18em] text-[#888]">Last updated</div>
                <div className="text-sm tabular-nums text-white">
                  {lastUpdated ? lastUpdated.toLocaleTimeString() : "—"}
                </div>
              </div>
              <div className="h-5 w-px bg-[rgba(255,255,255,0.1)]" />
              <div className="text-right">
                <div className="text-[11px] uppercase tracking-[0.18em] text-[#888]">Local time</div>
                <div className="text-sm tabular-nums text-white">
                  {clock ? clock.toLocaleTimeString() : "—"}
                </div>
              </div>
            </div>
          </header>

          <HeaderStats stats={snapshot.stats} />

          <div className="grid min-h-[calc(100vh-220px)] grid-cols-[minmax(0,1fr)_380px] gap-4 xl:grid-cols-[minmax(0,1fr)_430px]">
            <section className="overflow-hidden rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] p-2 backdrop-blur-md">
              <OperationsMap
                onlineDrivers={snapshot.onlineDrivers}
                requestedRides={snapshot.requestedRides}
                activeTrips={snapshot.activeTrips}
              />
            </section>
            <aside className="grid min-h-0 grid-rows-2 gap-4">
              <PendingRequestsPanel rides={snapshot.requestedRides} />
              <ActiveTripsPanel trips={snapshot.activeTrips} />
            </aside>
          </div>

          <ActivityFeedPanel events={activityEvents} />
        </div>
      </main>
    </DesktopGate>
  );
}

@import "tailwindcss";
@import "leaflet/dist/leaflet.css";

:root {
  --background: #0a0a0a;
  --foreground: #ffffff;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-midnight: #0a0a0a;
  --color-charcoal: #111111;
  --color-slate: #1a1a1a;
  --color-accent: #22c55e;
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
  background: #0a0a0a;
  color: #ffffff;
}

body {
  background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.03) 1px, transparent 0);
  background-size: 24px 24px;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0a0a0a;
}

::-webkit-scrollbar-thumb {
  background: #1a1a1a;
  border: 2px solid #0a0a0a;
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: #22c55e;
}

.leaflet-container {
  background: #111111;
  color: #ffffff;
}

.leaflet-tile {
  filter: grayscale(0.85) invert(1) contrast(0.85) brightness(0.75) brightness(0.8) contrast(1.1) saturate(0.7);
}

.map-marker {
  display: flex;
  height: 28px;
  width: 28px;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 2px solid #0a0a0a;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.75);
}

.map-marker-driver,
.map-marker-pickup {
  background: #22c55e;
}

.map-marker-request {
  animation: marker-pulse 1.4s ease-out infinite;
  background: #f59e0b;
}

.map-marker-dropoff {
  background: #ef4444;
}

@keyframes marker-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.8);
  }
  70% {
    box-shadow: 0 0 0 14px rgba(245, 158, 11, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0);
  }
}

/* Glassmorphism utilities */
.glass {
  background: rgba(17, 17, 17, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.glass-strong {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

/* Subtle border utility */
.border-subtle {
  border-color: rgba(255, 255, 255, 0.06);
}

