.stat-value {
  font-size: 32px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* Micro label */
.micro-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #888888;
}

/* Section title */
.section-title {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: #ffffff;
}

/* Timestamp */
.timestamp {
  font-family: var(--font-geist-mono), ui-monospace, monospace;
  font-size: 11px;
  color: #555555;
}

"use client";

import { Fragment, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import L from "leaflet";
import { MapContainer, Marker, Polyline, TileLayer, Tooltip, useMap } from "react-leaflet";
import type { ActiveTrip, OnlineDriver, RequestedRide } from "@/types/database";

type Point = { lat: number; lng: number };

type Props = {
  onlineDrivers: OnlineDriver[];
  requestedRides: RequestedRide[];
  activeTrips: ActiveTrip[];
};

const guyanaCenter: [number, number] = [6.8, -58.15];

function divIcon(className: string, label: string) {
  return L.divIcon({
    className: "",
    html: `<div class="${className}">${label}</div>`,
    iconSize: [28, 28],
    iconAnchor: [14, 14],
  });
}

const driverIcon = divIcon("map-marker map-marker-driver cursor-pointer", "🚗");
const requestIcon = divIcon("map-marker map-marker-request", "●");
const pickupIcon = divIcon("map-marker map-marker-pickup", "P");
const dropoffIcon = divIcon("map-marker map-marker-dropoff", "D");

function FitBounds({ points }: { points: Point[] }) {
  const map = useMap();

  useEffect(() => {
    if (points.length === 0) {
      map.setView(guyanaCenter, 12);
      return;
    }

    const bounds = L.latLngBounds(points.map((point) => [point.lat, point.lng]));
    map.fitBounds(bounds, { padding: [40, 40], maxZoom: 14 });
  }, [map, points]);

  return null;
}

export default function OperationsMap({ onlineDrivers, requestedRides, activeTrips }: Props) {
  const router = useRouter();

  const points = useMemo<Point[]>(() => {
    const driverPoints = onlineDrivers
      .filter((driver) => driver.current_lat != null && driver.current_lng != null)
      .map((driver) => ({ lat: Number(driver.current_lat), lng: Number(driver.current_lng) }));
    const requestPoints = requestedRides.map((ride) => ({ lat: ride.pickup_lat, lng: ride.pickup_lng }));
    const tripPoints = activeTrips.flatMap((trip) => [
      { lat: trip.pickup_lat, lng: trip.pickup_lng },
      { lat: trip.dropoff_lat, lng: trip.dropoff_lng },
    ]);

    return [...driverPoints, ...requestPoints, ...tripPoints];
  }, [onlineDrivers, requestedRides, activeTrips]);

  return (
    <MapContainer center={guyanaCenter} zoom={12} className="h-full min-h-[560px] w-full rounded-xl bg-charcoal">
      <TileLayer
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      <FitBounds points={points} />

      {onlineDrivers.map((driver) =>
        driver.current_lat != null && driver.current_lng != null ? (
          <Marker
            key={driver.id}
            position={[Number(driver.current_lat), Number(driver.current_lng)]}
            icon={driverIcon}
            eventHandlers={{ click: () => router.push("/driver/" + driver.id) }}

          >
            <Tooltip>{driver.profiles?.full_name ?? "Online driver"}</Tooltip>
          </Marker>
        ) : null,
      )}

      {requestedRides.map((ride) => (
        <Marker key={ride.id} position={[ride.pickup_lat, ride.pickup_lng]} icon={requestIcon}>
          <Tooltip>{ride.profiles?.full_name ?? "Requested ride"}</Tooltip>
        </Marker>
      ))}

      {activeTrips.map((trip) => (
        <Fragment key={trip.id}>
          <Marker position={[trip.pickup_lat, trip.pickup_lng]} icon={pickupIcon} />
          <Marker position={[trip.dropoff_lat, trip.dropoff_lng]} icon={dropoffIcon} />
          <Polyline positions={[[trip.pickup_lat, trip.pickup_lng], [trip.dropoff_lat, trip.dropoff_lng]]} color="#22c55e" />
        </Fragment>
      ))}
    </MapContainer>
  );
}

