content.text:
"use client";

import { Fragment } from "react";
import { useRouter } from "next/navigation";
import L from "leaflet";
import { MapContainer, Marker, Polyline, TileLayer, Tooltip } from "react-leaflet";
import type { ActiveTrip, OnlineDriver, RequestedRide } from "@/types/database";

type Props = {
  onlineDrivers: OnlineDriver[];
  requestedRides: RequestedRide[];
  activeTrips: ActiveTrip[];
};

function divIcon(className: string, label: string) {
  return L.divIcon({
    className: "",
    html: `<div class="${className}">${label}</div>`,
    iconSize: [28, 28],
    iconAnchor: [14, 14],
  });
}

const driverIcon = divIcon("map-marker map-marker-driver cursor-pointer", "🚗");
const requestIcon = divIcon("map-marker map-marker-request", "●");
const pickupIcon = divIcon("map-marker map-marker-pickup", "P");
const dropoffIcon = divIcon("map-marker map-marker-dropoff", "D");

export default function OperationsMap({ onlineDrivers, requestedRides, activeTrips }: Props) {
  const router = useRouter();

  return (
    <MapContainer center={guyanaCenter} zoom={12} className="h-full min-h-[560px] w-full rounded-xl bg-charcoal">
      <TileLayer
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      {onlineDrivers.map((driver) =>
        driver.current_lat != null && driver.current_lng != null ? (
          <Marker
            key={driver.id}
            position={[Number(driver.current_lat), Number(driver.current_lng)]}
            icon={driverIcon}
            eventHandlers={{ click: () => router.push("/driver/" + driver.id) }}

          >
            <Tooltip>{driver.profiles?.full_name ?? "Online driver"}</Tooltip>
          </Marker>
        ) : null,
      )}

      {requestedRides.map((ride) => (
        <Marker key={ride.id} position={[ride.pickup_lat, ride.pickup_lng]} icon={requestIcon}>
          <Tooltip>{ride.profiles?.full_name ?? "Requested ride"}</Tooltip>
        </Marker>
      ))}

      {activeTrips.map((trip) => (
        <Fragment key={trip.id}>
          <Marker position={[trip.pickup_lat, trip.pickup_lng]} icon={pickupIcon} />
          <Marker position={[trip.dropoff_lat, trip.dropoff_lng]} icon={dropoffIcon} />
          <Polyline positions={[[trip.pickup_lat, trip.pickup_lng], [trip.dropoff_lat, trip.dropoff_lng]]} color="#22c55e" />
        </Fragment>
      ))}
    </MapContainer>
  );
}

@import "tailwindcss";
@import "leaflet/dist/leaflet.css";

:root {
  --background: #0a0a0a;
  --foreground: #ffffff;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-midnight: #0a0a0a;
  --color-charcoal: #111111;
  --color-slate: #1a1a1a;
  --color-accent: #22c55e;
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
  background: #0a0a0a;
  color: #ffffff;
}

body {
  background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.03) 1px, transparent 0);
  background-size: 24px 24px;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0a0a0a;
}

::-webkit-scrollbar-thumb {
  background: #1a1a1a;
  border: 2px solid #0a0a0a;
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: #22c55e;
}

.leaflet-container {
  background: #111111;
  color: #ffffff;
}

.leaflet-tile {
  filter: grayscale(0.85) invert(1) contrast(0.85) brightness(0.75) brightness(0.8) contrast(1.1) saturate(0.7);
}

.map-marker {
  display: flex;
  height: 28px;
  width: 28px;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 2px solid #0a0a0a;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.75);
  animation: marker-pop-in 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  position: relative;
}

/* One-shot pulse ring on entrance */
.map-marker::before {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 999px;
  border: 3px solid transparent;
  animation: marker-ring 1s ease-out forwards;
  pointer-events: none;
}

.map-marker-driver::before {
  border-color: #22c55e;
}

.map-marker-request::before {
  border-color: #f59e0b;
}

.map-marker-pickup::before {
  border-color: #22c55e;
}

.map-marker-dropoff::before {
  border-color: #ef4444;
}

.map-marker-driver,
.map-marker-pickup {
  background: #22c55e;
}

.map-marker-request {
  background: #f59e0b;
}

.map-marker-dropoff {
  background: #ef4444;
}

@keyframes marker-pop-in {
  0% {
    opacity: 0;
    transform: scale(0);
  }
  60% {
    opacity: 1;
    transform: scale(1.2);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes marker-ring {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(2.5);
  }
}

/* Glassmorphism utilities */
.glass {
  background: rgba(17, 17, 17, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.glass-strong {
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

/* Subtle border utility */
.border-subtle {
  border-color: rgba(255, 255, 255, 0.06);
}

/* Stat value */
.stat-value {
  font-size: 32px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* Micro label */
.micro-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #888888;
}

/* Section title */
.section-title {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: #ffffff;
}

/* Timestamp */
.timestamp {
