import type { DashboardStats } from "@/types/database";

const cards = [
  { key: "onlineDrivers", label: "Online Drivers", icon: "●", color: "#22c55e" },
  { key: "requestedRides", label: "Pending Requests", icon: "◇", color: "#f59e0b" },
  { key: "activeTrips", label: "Active Trips", icon: "↗", color: "#3b82f6" },
  { key: "completedToday", label: "Completed Today", icon: "✓", color: "#a855f7" },
  { key: "revenueToday", label: "Revenue Today", icon: "GYD", color: "#14b8a6" },
] as const;

export function HeaderStats({ stats }: { stats: DashboardStats }) {
  return (
    <section className="grid grid-cols-2 gap-3 md:grid-cols-5">
      {cards.map((card) => {
        const value = stats[card.key];
        const displayValue =
          card.key === "revenueToday"
            ? new Intl.NumberFormat("en-GY").format(value)
            : value;

        return (
          <div
            key={card.key}
            className="relative overflow-hidden rounded-xl border border-[rgba(255,255,255,0.06)] p-4 transition-all duration-200 hover:-translate-y-0.5 hover:border-[rgba(255,255,255,0.12)]"
            style={{
              background: "linear-gradient(145deg, #111 0%, #0d0d0d 100%)",
              borderLeft: `3px solid ${card.color}`,
            }}
          >
            <div className="flex items-center justify-between">
              <span className="micro-label">{card.label}</span>
              <span className="text-xs opacity-40" style={{ color: card.color }}>
                {card.icon}
              </span>
            </div>
            <div className="stat-value mt-2 text-white">{displayValue}</div>
          </div>
        );
      })}
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { RequestedRide } from "@/types/database";

function relativeTime(dateString: string, now: number) {
  const diffSeconds = Math.round((new Date(dateString).getTime() - now) / 1000);
  const abs = Math.abs(diffSeconds);
  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

  if (abs < 60) return rtf.format(diffSeconds, "second");
  if (abs < 3600) return rtf.format(Math.round(diffSeconds / 60), "minute");
  return rtf.format(Math.round(diffSeconds / 3600), "hour");
}

export function PendingRequestsPanel({ rides }: { rides: RequestedRide[] }) {
  const [now, setNow] = useState<number | null>(null);

  useEffect(() => {
    setNow(Date.now());
  }, []);

  return (
    <section className="flex min-h-0 flex-col rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] backdrop-blur-md">
      <div className="border-b border-[rgba(255,255,255,0.06)] p-3">
        <h2 className="section-title">Pending Requests</h2>
      </div>
      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto p-3">
        {rides.length === 0 ? (
          <div className="rounded-lg border border-[rgba(255,255,255,0.06)] bg-midnight p-4 text-center text-xs text-[#666]">
            No pending requests
          </div>
        ) : (
          rides.map((ride) => (
            <article
              key={ride.id}
              className="relative overflow-hidden rounded-lg border border-[rgba(255,255,255,0.06)] bg-[#0f0f0f] p-2.5 pl-3"
              style={{ borderLeft: "3px solid #f59e0b" }}
            >
              <div className="mb-1 flex items-center justify-between gap-2">
                <strong className="truncate text-xs text-white">
                  {ride.profiles?.full_name ?? "Unknown passenger"}
                </strong>
                <span className="shrink-0 text-[10px] text-[#888]">
                  {now ? relativeTime(ride.created_at, now) : "—"}
                </span>
              </div>
              <p className="truncate text-[11px] text-[#888]">Pickup: {ride.pickup_address ?? "Unknown"}</p>
              <p className="truncate text-[11px] text-[#888]">Dropoff: {ride.dropoff_address ?? "Unknown"}</p>
              <div className="mt-2 flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500" />
                  <span className="text-[10px] uppercase tracking-wider text-amber-400">Pending</span>
                </div>
                <div className="text-xs font-bold tabular-nums text-accent">
                  GYD {new Intl.NumberFormat("en-GY").format(Number(ride.fare_estimate ?? 0))}
                </div>
              </div>
            </article>
          ))
        )}
      </div>
    </section>
  );
}

import type { ActiveTrip, RideStatus } from "@/types/database";

const statusOrder: RideStatus[] = ["accepted", "en_route", "arrived", "in_progress"];

const accentColor: Record<string, string> = {
  accepted: "#3b82f6",
  en_route: "#f59e0b",
  arrived: "#a855f7",
  in_progress: "#22c55e",
};

const badgeClass: Record<string, string> = {
  accepted: "bg-blue-500/15 text-blue-300",
  en_route: "bg-amber-500/15 text-amber-300",
  arrived: "bg-purple-500/15 text-purple-300",
  in_progress: "bg-green-500/15 text-green-300",
};

export function ActiveTripsPanel({ trips }: { trips: ActiveTrip[] }) {
  const grouped = statusOrder.map((status) => ({
    status,
    trips: trips.filter((trip) => trip.status === status),
  }));

  return (
    <section className="flex min-h-0 flex-col rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] backdrop-blur-md">
      <div className="border-b border-[rgba(255,255,255,0.06)] p-3">
        <h2 className="section-title">Active Trips</h2>
      </div>
      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-3">
        {trips.length === 0 ? (
          <div className="rounded-lg border border-[rgba(255,255,255,0.06)] bg-midnight p-4 text-center text-xs text-[#666]">
            No active trips
          </div>
        ) : (
          grouped.map((group) =>
            group.trips.length > 0 ? (
              <div key={group.status} className="space-y-2">
                <div className="text-[10px] uppercase tracking-[0.2em] text-[#666]">{group.status.replace("_", " ")}</div>
                {group.trips.map((trip) => (
                  <article
                    key={trip.id}
                    className="relative overflow-hidden rounded-lg border border-[rgba(255,255,255,0.06)] bg-[#0f0f0f] p-2.5 pl-3"
                    style={{ borderLeft: `3px solid ${accentColor[trip.status]}` }}
                  >
                    <div className="mb-1 flex items-center justify-between gap-2">
                      <div className="min-w-0 text-xs text-white">
                        <div className="truncate">
                          Driver:{" "}
                          <a href={"/driver/" + trip.driver_id} className="text-accent hover:underline">
                            {trip.driver_profile?.full_name ?? "Unassigned"}
                          </a>
                        </div>
                        <div className="truncate text-[#888]">Passenger: {trip.passenger?.full_name ?? "Unknown"}</div>
                      </div>
                      <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] uppercase ${badgeClass[trip.status]}`}>
                        {trip.status.replace("_", " ")}
                      </span>
                    </div>
                    <p className="truncate text-[11px] text-[#888]">
                      {trip.pickup_address ?? "Pickup unknown"} → {trip.dropoff_address ?? "Dropoff unknown"}
                    </p>
                    <div className="mt-2 text-xs font-bold tabular-nums text-accent">
                      GYD {new Intl.NumberFormat("en-GY").format(Number(trip.fare_final ?? trip.fare_estimate ?? 0))}
                    </div>
                  </article>
                ))}
              </div>
            ) : null,
          )
        )}
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { ActivityEvent } from "@/types/activity";

function formatTimeLabel(iso: string): string {
  try {
    return new Date(iso).toTimeString().slice(0, 8);
  } catch {
    return "--:--:--";
  }
}

function HighlightedMessage({ message }: { message: string }) {
  return (
    <span className="text-[#e5e5e5]">
      {message}
    </span>
  );
}

export function ActivityFeedPanel({ events }: { events: ActivityEvent[] }) {
  const [expanded, setExpanded] = useState(true);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (expanded && listRef.current) {
      listRef.current.scrollTop = 0;
    }
  }, [events, expanded]);

  const displayEvents = events.slice(0, 200);

  return (
    <div className="rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] backdrop-blur-md">
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className="flex w-full items-center justify-between px-4 py-2.5 text-left"
      >
        <div className="flex items-center gap-2">
          <span className="text-[11px] font-semibold uppercase tracking-[0.18em] text-[#888]">
            Activity Feed
          </span>
          {displayEvents.length > 0 && (
            <span className="rounded-full bg-[#1a1a1a] px-2 py-0.5 text-[10px] font-medium text-[#aaa]">
              {displayEvents.length}
            </span>
          )}
        </div>
        <span className="text-[10px] text-[#666]">{expanded ? "Collapse" : "Expand"}</span>
      </button>

      {expanded && (
        <div
          ref={listRef}
          className="flex max-h-[300px] flex-col gap-0.5 overflow-y-auto border-t border-[rgba(255,255,255,0.06)] px-3 py-2"
        >
          {displayEvents.length === 0 && (
            <div className="py-3 text-center text-[11px] text-[#555]">
              Waiting for activity…
            </div>
          )}
          {displayEvents.map((event) => (
            <div
              key={event.id}
              className="flex items-start gap-2 rounded-md px-2 py-1 hover:bg-[#1a1a1a]"
            >
              <span
                className="mt-1.5 h-2 w-2 flex-shrink-0 rounded-full"
                style={{ backgroundColor: event.color }}
              />
              <span className="flex-shrink-0 pt-0.5 font-mono text-[11px] text-[#555]">
                {formatTimeLabel(event.timestamp)}
              </span>
              <span className="text-xs text-[#ccc]">
                <HighlightedMessage message={event.message} />
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export function DesktopGate({ children }: { children: React.ReactNode }) {
  return (
    <>
      <div className="flex min-h-screen items-center justify-center bg-midnight p-8 text-center md:hidden">
        <div className="max-w-sm rounded-xl border border-[rgba(255,255,255,0.06)] bg-[rgba(17,17,17,0.8)] p-6 text-white backdrop-blur-md">
          <div className="mb-3 text-2xl">🖥️</div>
          <h2 className="mb-2 text-lg font-semibold">Desktop Required</h2>
          <p className="text-sm text-[#888]">
            This dashboard is designed for tablets and desktops. Please use a larger screen.
          </p>
        </div>
      </div>
      <div className="hidden md:block">{children}</div>
    </>
  );
}

export type ActivityEventType =
  | "driver_online"
  | "driver_offline"
  | "ride_requested"
  | "ride_accepted"
  | "ride_en_route"
  | "ride_arrived"
  | "ride_started"
  | "ride_completed"
  | "payment_received";

export type ActivityEvent = {
  id: string;
  type: ActivityEventType;
  message: string;
  timestamp: string;
  color: string;
};

