@import "tailwindcss";
@import "leaflet/dist/leaflet.css";

:root {
  --bg-deep: #0a0a0f;
  --bg-surface: #12121a;
  --bg-card: #1a1a24;
  --bg-elevated: #22222e;
  --border-subtle: rgba(255, 255, 255, 0.06);
  --border-medium: rgba(255, 255, 255, 0.1);
  --text-primary: #f5f5f5;
  --text-secondary: #a3a3a3;
  --text-muted: #525252;
  --accent: #22c55e;
  --accent-glow: rgba(34, 197, 94, 0.25);
  --amber: #f59e0b;
  --amber-glow: rgba(245, 158, 11, 0.25);
  --blue: #3b82f6;
  --blue-glow: rgba(59, 130, 246, 0.25);
  --purple: #a855f7;
  --purple-glow: rgba(168, 85, 247, 0.25);
  --red: #ef4444;
  --red-glow: rgba(239, 68, 68, 0.25);
  --teal: #14b8a6;
}

@theme inline {
  --color-bg-deep: var(--bg-deep);
  --color-bg-surface: var(--bg-surface);
  --color-bg-card: var(--bg-card);
  --color-bg-elevated: var(--bg-elevated);
  --color-text-primary: var(--text-primary);
  --color-text-secondary: var(--text-secondary);
  --color-text-muted: var(--text-muted);
  --color-accent: var(--accent);
  --color-amber: var(--amber);
  --color-blue: var(--blue);
  --color-purple: var(--purple);
  --color-red: var(--red);
  --color-teal: var(--teal);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
  background: var(--bg-deep);
  color: var(--text-primary);
}

body {
  background-image:
    radial-gradient(ellipse 80% 60% at 50% 0%, rgba(34, 197, 94, 0.04) 0%, transparent 60%),
    radial-gradient(ellipse 60% 40% at 80% 100%, rgba(59, 130, 246, 0.03) 0%, transparent 60%);
}

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--bg-elevated);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* ── Leaflet ─────────────────────────────────────────── */
.leaflet-container {
  background: var(--bg-surface);
  color: var(--text-primary);
}

.leaflet-tile {
  filter: grayscale(0.85) invert(1) contrast(0.85) brightness(0.75) saturate(0.7);
}

/* ── Map Markers ────────────────────────────────────── */
.map-marker {
  display: flex;
  height: 28px;
  width: 28px;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: 2px solid var(--bg-deep);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.75);
  animation: marker-pop-in 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  position: relative;
}

.map-marker::before {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 999px;
  border: 3px solid transparent;
  animation: marker-ring 1s ease-out forwards;
  pointer-events: none;
}

.map-marker-driver::before { border-color: var(--accent); }
.map-marker-request::before { border-color: var(--amber); }
.map-marker-pickup::before { border-color: var(--accent); }
.map-marker-dropoff::before { border-color: var(--red); }

.map-marker-driver,
.map-marker-pickup { background: var(--accent); }
.map-marker-request { background: var(--amber); }
.map-marker-dropoff { background: var(--red); }

@keyframes marker-pop-in {
  0%   { opacity: 0; transform: scale(0); }
  60%  { opacity: 1; transform: scale(1.2); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes marker-ring {
  0%   { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(2.5); }
}

/* ── Core Animations ────────────────────────────────── */
@keyframes fade-in-up {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes shimmer {
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

@keyframes glow-pulse {
  0%, 100% { opacity: 0.6; }
  50%      { opacity: 1; }
}

@keyframes border-flow {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes dot-grid {
  0%, 100% { opacity: 0.3; }
  50%      { opacity: 0.8; }
}

/* ── Glass Card ─────────────────────────────────────── */
.glass-card {
  background: rgba(26, 26, 36, 0.7);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
}

.glass-card-strong {
  background: rgba(26, 26, 36, 0.9);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border-medium);
  border-radius: 12px;
}

/* ── Status Badge ───────────────────────────────────── */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 9999px;
  padding: 3px 10px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  line-height: 1.4;
}

.status-badge.status-green {
  background: rgba(34, 197, 94, 0.12);
  color: #4ade80;
  box-shadow: inset 0 0 8px rgba(34, 197, 94, 0.08);
}

.status-badge.status-amber {
  background: rgba(245, 158, 11, 0.12);
  color: #fbbf24;
  box-shadow: inset 0 0 8px rgba(245, 158, 11, 0.08);
}

.status-badge.status-blue {
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
  box-shadow: inset 0 0 8px rgba(59, 130, 246, 0.08);
}

.status-badge.status-purple {
  background: rgba(168, 85, 247, 0.12);
  color: #c084fc;
  box-shadow: inset 0 0 8px rgba(168, 85, 247, 0.08);
}

.status-badge.status-red {
  background: rgba(239, 68, 68, 0.12);
  color: #f87171;
  box-shadow: inset 0 0 8px rgba(239, 68, 68, 0.08);
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  animation: dot-grid 2s ease-in-out infinite;
}

.status-green .status-dot { background: var(--accent); }
.status-amber .status-dot { background: var(--amber); }
.status-blue .status-dot { background: var(--blue); }
.status-purple .status-dot { background: var(--purple); }
.status-red .status-dot { background: var(--red); }

/* ── Typography ─────────────────────────────────────── */
.stat-value {
  font-size: 28px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.section-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--text-secondary);
}

/* ── Shimmer Sweep ──────────────────────────────────── */
.shimmer-container {
  position: relative;
  overflow: hidden;
}

.shimmer-container::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.04), transparent);
  animation: shimmer 3s ease-in-out infinite;
  pointer-events: none;
}

/* ── Panel Header ───────────────────────────────────── */
.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.panel-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--text-secondary);
}

/* ── List Item ──────────────────────────────────────── */
.list-item {
  padding: 10px 14px;
  border-radius: 8px;
  background: rgba(18, 18, 26, 0.6);
  border: 1px solid var(--border-subtle);
  transition: border-color 0.2s, background 0.2s;
}

.list-item:hover {
  border-color: var(--border-medium);
  background: rgba(26, 26, 36, 0.8);
}

/* ── Timeline ───────────────────────────────────────── */
.timeline-item {
  position: relative;
  padding-left: 28px;
  padding-top: 4px;
  padding-bottom: 4px;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: 9px;
  top: 14px;
  bottom: -14px;
  width: 1px;
  background: var(--border-subtle);
}

.timeline-item:last-child::before {
  display: none;
}

.timeline-dot {
  position: absolute;
  left: 5px;
  top: 10px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 2px solid var(--bg-deep);
}

"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { HeaderStats } from "./HeaderStats";
import { PendingRequestsPanel } from "./PendingRequestsPanel";
import { ActiveTripsPanel } from "./ActiveTripsPanel";
import { ActivityFeedPanel } from "./ActivityFeedPanel";
import { DesktopGate } from "./DesktopGate";
import type { DashboardSnapshot } from "@/types/database";
import type { ActivityEvent } from "@/types/activity";

const OperationsMap = dynamic(() => import("./OperationsMap"), {
  ssr: false,
  loading: () => (
    <div className="flex h-full min-h-[560px] items-center justify-center rounded-xl bg-bg-surface">
      <div className="flex flex-col items-center gap-3">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-accent border-t-transparent" />
        <span className="text-xs text-text-muted">Loading map…</span>
      </div>
    </div>
  ),
});

type ConnectionStatus = "connecting" | "connected" | "reconnecting";

export function DashboardShell({ initialSnapshot }: { initialSnapshot: DashboardSnapshot }) {
  const [snapshot, setSnapshot] = useState(initialSnapshot);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [activityEvents, setActivityEvents] = useState<ActivityEvent[]>([]);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>("connecting");
  const [clock, setClock] = useState<Date | null>(null);

  useEffect(() => {
    setLastUpdated(new Date());
    setClock(new Date());
    const interval = setInterval(() => setClock(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let es: EventSource | null = null;
    let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    let intentionalClose = false;

    function connect() {
      if (intentionalClose) return;
      setConnectionStatus((prev) => (prev === "connected" ? "reconnecting" : "connecting"));

      es = new EventSource("/api/events");

      es.addEventListener("snapshot", (e) => {
        try {
          const data = JSON.parse(e.data) as DashboardSnapshot;
          setSnapshot(data);
          setLastUpdated(new Date());
          setConnectionStatus("connected");
        } catch (err) {
          console.error("Failed to parse snapshot event", err);
        }
      });

      es.addEventListener("activity", (e) => {
        try {
          const data = JSON.parse(e.data) as ActivityEvent;
          setActivityEvents((prev) => [data, ...prev].slice(0, 200));
        } catch (err) {
          console.error("Failed to parse activity event", err);
        }
      });

      es.onopen = () => setConnectionStatus("connected");

      es.onerror = () => {
        setConnectionStatus("reconnecting");
        if (es) { es.close(); es = null; }
        if (!intentionalClose) {
          if (reconnectTimer) clearTimeout(reconnectTimer);
          reconnectTimer = setTimeout(() => { reconnectTimer = null; connect(); }, 3000);
        }
      };
    }

    connect();

    return () => {
      intentionalClose = true;
      if (reconnectTimer) clearTimeout(reconnectTimer);
      if (es) { es.close(); es = null; }
    };
  }, []);

  const isConnected = connectionStatus === "connected";
  const statusColor = isConnected ? "var(--accent)" : "var(--amber)";
  const statusText = isConnected ? "LIVE" : "RECONNECTING";

  return (
    <DesktopGate>
      <main className="min-h-screen bg-bg-deep p-4 text-white lg:p-5">
        <div className="mx-auto flex max-w-[1760px] flex-col gap-4">

          {/* ── Top Bar ─────────────────────────────── */}
          <header className="glass-card flex items-center justify-between px-5 py-3">
            <div className="flex items-center gap-4">
              {/* Live indicator */}
              <div className="flex items-center gap-2.5">
                <span
                  className="relative flex h-2.5 w-2.5"
                >
                  <span
                    className="absolute inline-flex h-full w-full animate-ping rounded-full opacity-75"
                    style={{ backgroundColor: statusColor }}
                  />
                  <span
                    className="relative inline-flex h-2.5 w-2.5 rounded-full"
                    style={{ backgroundColor: statusColor }}
                  />
                </span>
                <span
                  className="text-[10px] font-bold uppercase tracking-[0.22em]"
                  style={{ color: statusColor }}
                >
                  {statusText}
                </span>
              </div>

              <div className="h-5 w-px bg-border-subtle" />

              <h1 className="text-lg font-semibold tracking-tight">Command Center</h1>
            </div>

            <div className="flex items-center gap-5">
              <div className="text-right">
                <div className="text-[10px] uppercase tracking-[0.16em] text-text-muted">Last updated</div>
                <div className="text-xs font-mono text-text-secondary">
                  {lastUpdated ? lastUpdated.toLocaleTimeString() : "—"}
                </div>
              </div>
              <div className="h-5 w-px bg-border-subtle" />
              <div className="text-right">
                <div className="text-[10px] uppercase tracking-[0.16em] text-text-muted">Local time</div>
                <div className="text-xs font-mono text-text-secondary">
                  {clock ? clock.toLocaleTimeString() : "—"}
                </div>
              </div>
            </div>
          </header>

          {/* ── Stats Row ────────────────────────────── */}
          <HeaderStats stats={snapshot.stats} />

          {/* ── Main Grid ────────────────────────────── */}
          <div className="grid min-h-[calc(100vh-260px)] grid-cols-[minmax(0,1fr)_380px] gap-4 xl:grid-cols-[minmax(0,1fr)_420px]">

            {/* Map Panel */}
            <section className="glass-card overflow-hidden p-1.5">
              <OperationsMap
                onlineDrivers={snapshot.onlineDrivers}
                requestedRides={snapshot.requestedRides}
                activeTrips={snapshot.activeTrips}
              />
            </section>

            {/* Right Sidebar */}
            <aside className="flex flex-col gap-4">
              <div className="flex min-h-0 flex-1 flex-col glass-card overflow-hidden">
                <PendingRequestsPanel rides={snapshot.requestedRides} />
              </div>
              <div className="flex min-h-0 flex-1 flex-col glass-card overflow-hidden">
                <ActiveTripsPanel trips={snapshot.activeTrips} />
              </div>
            </aside>
          </div>

          {/* ── Activity Feed ────────────────────────── */}
          <ActivityFeedPanel events={activityEvents} />

        </div>
      </main>
    </DesktopGate>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { DashboardStats } from "@/types/database";

const cards = [
  { key: "onlineDrivers" as const, label: "Online Drivers", icon: "●", color: "var(--accent)", glow: "var(--accent-glow)" },
  { key: "requestedRides" as const, label: "Pending Requests", icon: "◇", color: "var(--amber)", glow: "var(--amber-glow)" },
  { key: "activeTrips" as const, label: "Active Trips", icon: "↗", color: "var(--blue)", glow: "var(--blue-glow)" },
  { key: "completedToday" as const, label: "Completed Today", icon: "✓", color: "var(--purple)", glow: "var(--purple-glow)" },
  { key: "revenueToday" as const, label: "Revenue Today", icon: "GYD", color: "var(--teal)", glow: "rgba(20,184,166,0.25)" },
] as const;

function CountUp({ value, prefix = "", suffix = "", duration = 600 }: { value: number; prefix?: string; suffix?: string; duration?: number }) {
  const ref = useRef<HTMLSpanElement>(null);
  const prevRef = useRef(value);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const start = prevRef.current;
    const end = value;
    if (start === end) return;

    prevRef.current = end;
    const startTime = performance.now();

    function tick(now: number) {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      // ease-out cubic
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(start + (end - start) * eased);
      el.textContent = prefix + current.toLocaleString("en-GY") + suffix;
      if (progress < 1) requestAnimationFrame(tick);
    }

    requestAnimationFrame(tick);
  }, [value, prefix, suffix, duration]);

  return <span ref={ref}>{prefix}{value.toLocaleString("en-GY")}{suffix}</span>;
}

export function HeaderStats({ stats }: { stats: DashboardStats }) {
  return (
    <section className="grid grid-cols-2 gap-3 md:grid-cols-5">
      {cards.map((card) => {
        const value = stats[card.key];
        const displayValue =
          card.key === "revenueToday"
            ? new Intl.NumberFormat("en-GY").format(value)
            : value;

        return (
          <div
            key={card.key}
            className="glass-card shimmer-container p-4"
            style={{
              boxShadow: `0 4px 24px -8px ${card.glow}`,
              borderTop: `1px solid ${card.color}40`,
            }}
          >
            <div className="flex items-center justify-between">
              <span className="section-label">{card.label}</span>
              <span
                className="text-sm opacity-80"
                style={{ color: card.color }}
              >
                {card.icon}
              </span>
            </div>
            <div className="stat-value mt-2 text-white" style={{ color: card.key === "revenueToday" ? "var(--teal)" : "var(--text-primary)" }}>
              {card.key === "revenueToday" ? (
                <CountUp value={value} prefix="GYD " duration={800} />
              ) : (
                <CountUp value={value} duration={400} />
              )}
            </div>
          </div>
        );
      })}
    </section>
  );
}

