"use client";

import type { ActiveTrip, RideStatus } from "@/types/database";

const statusOrder: RideStatus[] = ["accepted", "en_route", "arrived", "in_progress"];

const statusConfig: Record<string, { color: string; badge: string; borderColor: string }> = {
  accepted:   { color: "var(--blue)",   badge: "status-blue",  borderColor: "border-l-blue" },
  en_route:   { color: "var(--amber)",  badge: "status-amber", borderColor: "border-l-amber" },
  arrived:    { color: "var(--purple)", badge: "status-purple",borderColor: "border-l-purple" },
  in_progress:{ color: "var(--accent)", badge: "status-green", borderColor: "border-l-accent" },
};

export function ActiveTripsPanel({ trips }: { trips: ActiveTrip[] }) {
  const grouped = statusOrder.map((status) => ({
    status,
    trips: trips.filter((trip) => trip.status === status),
  }));

  return (
    <>
      <div className="panel-header">
        <span className="panel-title">Active Trips</span>
        <span className="rounded-full bg-blue-500/10 px-2 py-0.5 text-[10px] font-bold text-blue-400">
          {trips.length}
        </span>
      </div>

      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-3">
        {trips.length === 0 ? (
          <div className="flex flex-col items-center justify-center gap-3 py-10">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-500/10">
              <span className="text-xl opacity-60">↗</span>
            </div>
            <p className="text-xs text-text-muted">No active trips</p>
          </div>
        ) : (
          grouped.map((group) =>
            group.trips.length > 0 ? (
              <div key={group.status} className="space-y-1.5">
                <div className="text-[10px] font-semibold uppercase tracking-[0.15em] text-text-muted px-1">
                  {group.status.replace("_", " ")}
                  <span className="ml-2 rounded-full bg-white/5 px-1.5 py-0.5 text-[10px] font-normal text-text-secondary">
                    {group.trips.length}
                  </span>
                </div>
                {group.trips.map((trip) => {
                  const cfg = statusConfig[trip.status];
                  return (
                    <article
                      key={trip.id}
                      className={`list-item cursor-pointer border-l-3 ${cfg.borderColor}`}
                    >
                      <div className="mb-1.5 flex items-start justify-between gap-2">
                        <div className="min-w-0 text-xs text-text-primary">
                          <div className="truncate font-medium">
                            Driver:{" "}
                            <a
                              href={"/driver/" + trip.driver_id}
                              className="text-accent hover:underline"
                            >
                              {trip.driver_profile?.full_name ?? "Unassigned"}
                            </a>
                          </div>
                          <div className="truncate text-text-secondary">
                            Passenger: {trip.passenger?.full_name ?? "Unknown"}
                          </div>
                        </div>
                        <span className={`status-badge ${cfg.badge} shrink-0`}>
                          <span className="status-dot" />
                          {trip.status.replace("_", " ")}
                        </span>
                      </div>

                      <p className="truncate text-[11px] text-text-secondary">
                        {trip.pickup_address ?? "Pickup unknown"}
                        <span className="mx-1.5 text-text-muted">→</span>
                        {trip.dropoff_address ?? "Dropoff unknown"}
                      </p>

                      <div className="mt-2 text-xs font-bold font-mono text-accent">
                        GYD {new Intl.NumberFormat("en-GY").format(Number(trip.fare_final ?? trip.fare_estimate ?? 0))}
                      </div>
                    </article>
                  );
                })}
              </div>
            ) : null,
          )
        )}
      </div>
    </>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { ActivityEvent } from "@/types/activity";

function formatTimeLabel(iso: string): string {
  try {
    return new Date(iso).toTimeString().slice(0, 8);
  } catch {
    return "--:--:--";
  }
}

export function ActivityFeedPanel({ events }: { events: ActivityEvent[] }) {
  const [expanded, setExpanded] = useState(true);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (expanded && listRef.current) {
      listRef.current.scrollTop = 0;
    }
  }, [events, expanded]);

  const displayEvents = events.slice(0, 200);

  return (
    <div className="glass-card overflow-hidden">
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className="flex w-full items-center justify-between px-4 py-3 text-left transition-colors hover:bg-white/5"
      >
        <div className="flex items-center gap-2.5">
          <span className="section-label">Activity Feed</span>
          {displayEvents.length > 0 && (
            <span className="rounded-full bg-white/5 px-2 py-0.5 text-[10px] font-mono text-text-secondary">
              {displayEvents.length}
            </span>
          )}
        </div>
        <span className="text-[10px] text-text-muted">
          {expanded ? "− Collapse" : "+ Expand"}
        </span>
      </button>

      {expanded && (
        <div
          ref={listRef}
          className="flex max-h-[280px] flex-col gap-0 overflow-y-auto border-t border-border-subtle px-4 py-3"
        >
          {displayEvents.length === 0 ? (
            <div className="py-4 text-center text-[11px] text-text-muted">
              Waiting for activity…
            </div>
          ) : (
            displayEvents.map((event, idx) => (
              <div
                key={event.id}
                className="timeline-item flex items-start gap-3 py-1.5"
              >
                <span
                  className="timeline-dot"
                  style={{ backgroundColor: event.color, boxShadow: `0 0 8px ${event.color}40` }}
                />
                <span className="flex-shrink-0 pt-0.5 font-mono text-[10px] text-text-muted">
                  {formatTimeLabel(event.timestamp)}
                </span>
                <span className="text-xs text-text-secondary leading-relaxed">
                  {event.message}
                </span>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

