"use client";

import { useMemo, useState } from "react";
import { getMockDriverData } from "@/lib/mock-driver-data";
import type { Ride, RideStatus } from "@/types/database";

const statusBadgeClass: Record<RideStatus | string, string> = {
  requested: "bg-amber-500/20 text-amber-300 border-amber-500/40",
  accepted: "bg-blue-500/20 text-blue-300 border-blue-500/40",
  en_route: "bg-blue-500/20 text-blue-300 border-blue-500/40",
  arrived: "bg-purple-500/20 text-purple-300 border-purple-500/40",
  in_progress: "bg-green-500/20 text-green-300 border-green-500/40",
  completed: "bg-green-500/20 text-green-300 border-green-500/40",
  cancelled: "bg-red-500/20 text-red-300 border-red-500/40",
};

function formatDate(dateStr: string | null) {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function formatTime(dateStr: string | null) {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

function formatCurrency(amount: number | null) {
  return `GYD ${new Intl.NumberFormat("en-GY").format(Number(amount ?? 0))}`;
}

export function DriverDetailPage({ driver, rides }: { driver: Record<string, unknown> | null; rides: Ride[] }) {
  const [range, setRange] = useState<string>("all");
  const mock = getMockDriverData();

  const status = (driver?.status as string) ?? "offline";
  const isOnline = driver?.is_online === true;

  const statusBadge = isOnline
    ? status === "in_progress" || status === "accepted" || status === "en_route" || status === "arrived"
      ? { label: "In Trip", className: "bg-amber-500/20 text-amber-300 border-amber-500/40" }
      : { label: "Online", className: "bg-green-500/20 text-green-300 border-green-500/40" }
    : { label: "Offline", className: "bg-gray-500/20 text-gray-300 border-gray-500/40" };

  const filteredRides = useMemo(() => {
    if (range === "all") return rides;
    const now = new Date();
    const cutoff = new Date();
    if (range === "today") {
      cutoff.setHours(0, 0, 0, 0);
    } else if (range === "week") {
      cutoff.setDate(now.getDate() - 7);
      cutoff.setHours(0, 0, 0, 0);
    } else if (range === "month") {
      cutoff.setDate(now.getDate() - 30);
      cutoff.setHours(0, 0, 0, 0);
    }
    return rides.filter((ride) => new Date(ride.created_at) >= cutoff);
  }, [rides, range]);

  return (
    <main className="min-h-screen bg-midnight p-4 text-white lg:p-6">
      <div className="mx-auto max-w-[1200px] space-y-4">
        <a
          href="/"
          className="inline-block text-sm text-accent hover:underline"
        >
          ← Back to Dashboard
        </a>

        <div className="rounded-xl border border-slate bg-charcoal p-5">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h1 className="text-2xl font-semibold tracking-tight">
                {(driver?.profiles as Record<string, string> | undefined)?.full_name ?? "Unknown Driver"}
              </h1>
              <p className="mt-1 text-sm text-[#aaa]">
                {(driver?.profiles as Record<string, string> | undefined)?.phone ?? "—"}
              </p>
            </div>
            <span className={`shrink-0 self-start rounded-full border px-3 py-1 text-xs uppercase ${statusBadge.className}`}>
              {statusBadge.label}
            </span>
          </div>

          <div className="mt-4 grid grid-cols-2 gap-4 sm:grid-cols-4">
            <div className="rounded-lg border border-slate bg-midnight p-3">
              <div className="text-xs uppercase tracking-[0.2em] text-[#666]">License Plate</div>
              <div className="mt-1 text-sm font-medium">{(driver?.license_plate as string) ?? "—"}</div>
            </div>
            <div className="rounded-lg border border-slate bg-midnight p-3">
              <div className="text-xs uppercase tracking-[0.2em] text-[#666]">Rating</div>
