import { getDriverDetail, getDriverRides } from "@/lib/queries";
import { DriverDetailPage } from "@/components/DriverDetailPage";

export const dynamic = "force-dynamic";

export default async function DriverPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const driver = await getDriverDetail(id);
  const rides = await getDriverRides(id, "all");

  return <DriverDetailPage driver={driver} rides={rides} />;
