"use client";

import { useMemo, useState } from "react";
import { getMockDriverData } from "@/lib/mock-driver-data";
import type { Ride, RideStatus } from "@/types/database";

const statusBadgeClass: Record<RideStatus | string, string> = {
  requested:   "status-amber",
  accepted:    "status-blue",
  en_route:    "status-blue",
  arrived:     "status-purple",
  in_progress: "status-green",
  completed:   "status-green",
  cancelled:   "status-red",
};

function formatDate(dateStr: string | null) {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function formatTime(dateStr: string | null) {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", hour12: true });
}

function formatCurrency(amount: number | null) {
  return `GYD ${new Intl.NumberFormat("en-GY").format(Number(amount ?? 0))}`;
}

function InfoCard({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="glass-card p-5">
      <h2 className="mb-4 section-label">{title}</h2>
      {children}
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between py-1.5 border-b border-border-subtle last:border-0">
      <span className="text-xs text-text-muted">{label}</span>
      <span className="text-xs font-medium text-text-secondary">{value}</span>
    </div>
  );
}

export function DriverDetailPage({ driver, rides }: { driver: Record<string, unknown> | null; rides: Ride[] }) {
  const [range, setRange] = useState<string>("all");
  const mock = getMockDriverData();

  const isOnline = driver?.is_online === true;
  const status = (driver?.status as string) ?? "offline";

  const statusBadge = isOnline
    ? ["in_progress", "accepted", "en_route", "arrived"].includes(status)
      ? { label: "In Trip", className: "status-amber" }
      : { label: "Online", className: "status-green" }
    : { label: "Offline", className: "status-red" };

  const filteredRides = useMemo(() => {
    if (range === "all") return rides;
    const now = new Date();
    const cutoff = new Date();
    if (range === "today") { cutoff.setHours(0, 0, 0, 0); }
    else if (range === "week") { cutoff.setDate(now.getDate() - 7); cutoff.setHours(0, 0, 0, 0); }
    else if (range === "month") { cutoff.setDate(now.getDate() - 30); cutoff.setHours(0, 0, 0, 0); }
    return rides.filter((ride) => new Date(ride.created_at) >= cutoff);
  }, [rides, range]);

  return (
    <main className="min-h-screen bg-bg-deep p-4 text-white lg:p-6">
      <div className="mx-auto max-w-[1200px] space-y-4">

        {/* Back link */}
        <a href="/" className="inline-flex items-center gap-1.5 text-sm text-text-muted hover:text-accent transition-colors">
          <span>←</span> Back to Dashboard
        </a>

        {/* Driver Header */}
        <div className="glass-card p-5">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h1 className="text-xl font-semibold tracking-tight">
                {(driver?.profiles as Record<string, string> | undefined)?.full_name ?? "Unknown Driver"}
              </h1>
              <p className="mt-1 text-sm font-mono text-text-muted">
                {(driver?.profiles as Record<string, string> | undefined)?.phone ?? "—"}
              </p>
            </div>
            <span className={`status-badge ${statusBadge.className} self-start`}>
              <span className="status-dot" />
              {statusBadge.label}
            </span>
          </div>

          {/* Quick Stats */}
          <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div className="rounded-lg bg-bg-surface p-3 border border-border-subtle">
              <div className="text-[10px] uppercase tracking-[0.15em] text-text-muted">License Plate</div>
              <div className="mt-1 text-sm font-medium">{(driver?.license_plate as string) ?? "—"}</div>
            </div>
            <div className="rounded-lg bg-bg-surface p-3 border border-border-subtle">
              <div className="text-[10px] uppercase tracking-[0.15em] text-text-muted">Rating</div>
              <div className="mt-1 text-sm font-medium">
                {driver?.rating_avg != null ? `${driver.rating_avg} ★` : "—"}
              </div>
            </div>
            <div className="rounded-lg bg-bg-surface p-3 border border-border-subtle">
              <div className="text-[10px] uppercase tracking-[0.15em] text-text-muted">Total Rides</div>
              <div className="mt-1 text-sm font-medium">{driver?.total_rides != null ? String(driver.total_rides) : "—"}</div>
            </div>
            <div className="rounded-lg bg-bg-surface p-3 border border-border-subtle">
              <div className="text-[10px] uppercase tracking-[0.15em] text-text-muted">Last Updated</div>
              <div className="mt-1 text-sm font-medium font-mono text-text-secondary">
                {driver?.current_location_updated_at ? formatTime(driver.current_location_updated_at) : "—"}
              </div>
            </div>
          </div>
        </div>

        {/* Info Cards Row */}
        <div className="grid gap-4 sm:grid-cols-3">
          <InfoCard title="Vehicle">
            <InfoRow label="Make" value={mock.vehicle.make} />
            <InfoRow label="Model" value={mock.vehicle.model} />
            <InfoRow label="Year" value={mock.vehicle.year} />
            <InfoRow label="Color" value={mock.vehicle.color} />
          </InfoCard>

          <InfoCard title="Documents">
            <InfoRow label="License Expiry" value={mock.documents.licenseExpiry} />
            <InfoRow label="Insurance Expiry" value={mock.documents.insuranceExpiry} />
            <InfoRow label="Inspection" value={mock.documents.vehicleInspection} />
            <div className="flex items-center justify-between py-1.5">
              <span className="text-xs text-text-muted">Status</span>
              <span className="status-badge status-green">
                <span className="status-dot" />
                {mock.documents.status}
              </span>
            </div>
          </InfoCard>

          <InfoCard title="Performance">
            <InfoRow label="Acceptance Rate" value={`${mock.performance.acceptanceRate}%`} />
            <InfoRow label="Completion Rate" value={`${mock.performance.completionRate}%`} />
            <InfoRow label="Avg Pickup" value={mock.performance.avgPickupTime} />
            <InfoRow label="Cancellation" value={`${mock.performance.cancellationRate}%`} />
          </InfoCard>
        </div>

        {/* Ride History */}
        <div className="glass-card">
          <div className="flex flex-col gap-3 border-b border-border-subtle p-4 sm:flex-row sm:items-center sm:justify-between">
            <h2 className="section-label">Ride History</h2>
            <select
              value={range}
              onChange={(e) => setRange(e.target.value)}
              className="rounded-lg border border-border-medium bg-bg-surface px-3 py-1.5 text-xs font-mono text-text-secondary outline-none focus:border-accent transition-colors"
            >
              <option value="today">Today</option>
              <option value="week">This Week</option>
              <option value="month">This Month</option>
              <option value="all">All Time</option>
            </select>
          </div>

          <div className="p-4">
            {filteredRides.length === 0 ? (
              <div className="flex flex-col items-center justify-center gap-3 py-10">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white/5">
                  <span className="text-xl opacity-40">↗</span>
                </div>
                <p className="text-xs text-text-muted">No rides found</p>
              </div>
            ) : (
              <div className="space-y-2">
                {filteredRides.map((ride) => (
                  <div
                    key={ride.id}
                    className="flex flex-col gap-2 rounded-lg border border-border-subtle bg-bg-surface p-3 sm:flex-row sm:items-center sm:justify-between hover:border-border-medium transition-colors"
                  >
                    <div className="min-w-0">
                      <div className="text-[10px] font-mono text-text-muted">
                        {formatDate(ride.created_at)} · {formatTime(ride.created_at)}
                      </div>
                      <div className="mt-1 truncate text-sm text-text-secondary">
                        {ride.pickup_address ?? "Pickup unknown"}
                        <span className="mx-2 text-text-muted">→</span>
                        {ride.dropoff_address ?? "Dropoff unknown"}
                      </div>
                    </div>
                    <div className="flex items-center gap-3 self-end sm:self-auto">
                      <span className="text-sm font-bold font-mono text-accent">
                        {formatCurrency(ride.fare_final ?? ride.fare_estimate)}
                      </span>
                      <span className={`status-badge ${statusBadgeClass[ride.status] ?? "status-red"}`}>
                        <span className="status-dot" />
                        {ride.status.replace("_", " ")}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

      </div>
    </main>
  );
}

